/* Further reading for existing entries, checked against 2020 SP1 QRG remarks. */
(() => {
 const byKey=new Map(window.InputCatalog.entries.map(e=>[e.key,e]));
 const update=(key,data)=>Object.assign(byKey.get(key),data);
 update('CELAS2',{
  title:'剛性を直接指定するスカラばね',
  summary:'選択した2つの自由度の相対変位に比例するばね力を定義します。剛性Kは要素へ直接入力し、PELASは参照しません。節点間距離や結線方向から自動的に剛性・作用方向が決まる要素ではありません。',
  sourcePages:[1541],
  connections:[['CELAS1 / PELAS','同じ特性を複数要素で共用する場合のプロパティ参照方式です。','CELAS1'],['CELAS4','スカラ点と固定基準だけを使う簡潔な書式です。','CELAS4'],['GRID','成分C1/C2は各節点のCDに従います。','GRID'],['CASE FORCE','ばね力の出力を要求します。','CASE_FORCE']],
  notes:['G1/C1とG2/C2は異なる自由度を指定します。同じ節点でも異なる成分は別自由度ですが、意図した連成か確認が必要です。','スカラ点の成分は0または空欄、固定基準側は節点と成分を0または空欄にします。GRIDの成分を未指定のままにする意味とは異なります。','構造減衰GEは臨界減衰比の2倍に対応します。過渡解析ではPARAM/W4を指定しなければGEは無視されます。'],
  outputs:['ばねの力と両端自由度の変位差が、採用した符号規約でKと対応するかを確認します。回転ばねでは力がモーメント、変位がラジアンになり、Kの単位も変わります。'],
  sections:[{title:'結合方向と剛性の選び方',paragraphs:['両端のCDが異なる場合、同じ成分番号でも空間的に同じ向きとは限りません。CELAS2は指定自由度を直接結ぶため、斜め方向の軸ばねを作るときは適切な節点変位座標系またはCBUSH等を検討します。','並進ばねは力/長さ、回転ばねはモーメント/ラジアンを入力します。剛性Kを大きくすると拘束へ近づきますが、極端な剛性比は数値条件を悪くします。剛体関係が目的ならMPC/RBE系の適用条件と比較します。']}]
 });
 update('CONM2',{
  title:'重心と回転慣性を持つ集中質量',
  summary:'GRIDへ質量・重心の偏心・重心回り慣性を持つ集中質量を接続します。例の0.01はN・mm・s系で10 kgに相当します。付加重量の力ではなく、質量行列を定義するカードです。',
  sourcePages:[1600,1601],
  notes:['CID=-1だけはX1/X2/X3を基本座標系の重心絶対座標として読みます。他のCIDでは節点から重心へのオフセットです。','CIDが円筒・球座標系を参照しても、オフセットは節点位置の局所直交軸に沿った距離成分です。r・θ・zやr・θ・φの座標値ではありません。','I21/I31/I32は慣性乗積です。慣性行列の非対角成分へ付く負符号はソルバーが付与します。別ソフトの行列値をそのまま転記すると符号が逆になる場合があります。'],
  connections:[['CONM1','より一般的な6×6質量行列を直接定義する場合の書式です。','CONM1'],['PARAM / GRDPNT','質量・重心・慣性の一覧で入力を確認します。','PARAM_GRDPNT'],['GRAV','重力加速度を与え、質量から荷重を生成します。','GRAV']],
  outputs:['質量合計、重心、慣性テンソルを手計算と比較します。偏心による平行軸の項を重心回りIijへ二重に加えないようにします。','慣性行列が非正定値の場合は警告が出て、動解析の後段でFATALとなることもあります。対角値・慣性乗積・単位を確認します。'],
  sections:[{title:'継続行の慣性を使う場合',paragraphs:['この入力例では重心を節点に一致させ、継続行を省略しています。回転慣性を与える場合は第1行の継続欄へ識別子を付け、次行の第2～7欄へI11,I21,I22,I31,I32,I33を置きます。Iijは重心を通る軸についての値です。','対角成分はI11=∫(x2²+x3²)dm、I22=∫(x1²+x3²)dm、I33=∫(x1²+x2²)dm。慣性乗積はI21=∫x1x2 dm、I31=∫x1x3 dm、I32=∫x2x3 dmです。寸法がmmなら慣性の長さ部分もmm²にそろえます。','調和構造節点（PAXSYMHに関係するCQUADX/CTRIAXの節点）ではMは全質量で2πを掛けません。この特殊用途ではCID・オフセット・Iijが無視されます。通常の6自由度GRIDとは扱いが異なります。']}]
 });
 update('EIGRL',{
  sourcePages:[1959,1960,1961,1962],
  notes:['振動ではV1/V2はcycles/時間、座屈では基準の応力状態に対する荷重倍率です。同じ数値欄でもSOL103とSOL105で単位と物理的意味が変わります。','V1を0.とすると負の固有値は探索されません。微小な負の値は剛体モードの計算誤差の場合がありますが、有限の負値は剛性・拘束・初期応力等の診断対象です。','MASSは一般化質量1、MAXは解析集合内の最大変位1に正規化します。座屈ではMASSを指定してもMAXとなり、正規化された変位を実際のたわみ量と解釈しません。'],
  connections:[['METHOD','このSIDを選択するCase Controlです。','CASE_METHOD'],['EIGR','Lanczos以外の実固有値抽出方法と比較します。','EIGR'],['FREQ1','荷重を加える周波数点は別の入力です。','FREQ1'],['CASE DISPLACEMENT','固有ベクトルの出力を要求します。','CASE_DISPLACEMENT']],
  outputs:['得られたモード数・固有値範囲・剛体モード数を要求条件と比較します。探索した全ての根が出力されるとは限らず、範囲確認のため内部で追加計算する場合があります。'],
  sections:[{title:'V1・V2・NDの組合せ（QRG Table 9-13）',paragraphs:['V1・V2・NDを全て指定：範囲内の根数とNDの小さい方まで。V1・V2だけ指定：範囲内の全て。V1とNDだけ指定：V1以上でND個。V1だけ指定：V1以上で1個。','NDだけ指定：全域を対象にND個。3欄とも空欄：最小の根1個。V2とNDだけ指定：V2未満でND個。V2だけ指定：V2未満の全て。根はゼロに近いものから探索され、負の固有値の扱いはV1の指定と合わせて読みます。']},{title:'診断・内部ブロック・分散並列',paragraphs:['MSGLVL=0は診断出力抑止、1はシフトごとの受理固有値、さらに大きな値は詳細を増やします。MAXSETは要求モード数ではなく内部ブロック上限です。QRG備考14では通常7で、環境のSYSTEM設定やメモリによって変わるため、最初は省略値を使います。','SHFSCLは最初の弾性モード周波数の推定値です。大質量法などで剛体・弾性モード間が大きく離れる場合の計算補助で、省略時は自動推定します。','任意継続行のoption=valueではSID以外の欄を設定できます。第1行に値を書いた項目を二重指定しません。ALPH・NUMS・Fiはこの形式専用で、分散並列時の周波数区間を制御します。V1とV2を指定し、NUMS>1で分割します。ALPH=1は等間隔の境界、Fiは直接指定した境界で、整合するFiがALPHより優先します。']}]
 });
 update('TABDMP1',{
  sourcePages:[3213,3214,3215],
  notes:['TYPE=G（省略時）はg、CRITは臨界減衰比ζ、Qは品質係数です。関係はg=2ζ、Q=1/(2ζ)=1/g。同じ0.02でもGならζ=1%、CRITならζ=2%です。','周波数は全体を昇順または降順へそろえ、少なくとも1本の継続行を置きます。終端ENDT以降にデータ継続を置いてはいけません。','端の2点では不連続を定義できません。内部の不連続点では両側の値の平均を使用します。SKIPをfまたはgのどちらかへ書くと、その対を除外します。','表の外側では端の2点を使った線形外挿です。外挿または負の減衰には警告が出て、外挿の結果が負なら通常FATALになります。適用する全モードの周波数を覆う表を作ります。'],
  connections:[['SDAMPING','モーダル減衰表を選択します。','CASE_SDAMPING'],['PARAM / KDAMP','モーダル周波数・複素固有値解析で粘性型/構造型への組込みを選びます。','PARAM_KDAMP'],['EIGRL','減衰表を評価する固有振動数を求めます。','EIGRL'],['CDAMP2','物理自由度間に置く粘性減衰要素との違いを確認します。','CDAMP2']],
  outputs:['モードごとの周波数と実際に使われた減衰を確認します。加振周波数ごとに減衰値を切り替える荷重テーブルとは用途が異なります。','構造減衰、粘性要素、モーダル減衰を併用する場合は寄与が重なります。共振の高さを合わせるために同じ減衰源を複数の方式へ重複入力しないようにします。']
 });
})();
